<?php// Looking to send emails in production? Check out our Email API/SMTP product!function tnw_send_mail_config($phpmailer) {	$setting_website     = get_option( '_shw_settings_set_smtp');	$phpmailer->isSMTP();	$phpmailer->Host     = $setting_website['host'];	$phpmailer->SMTPAuth = true;	$phpmailer->Port     =$setting_website['port'];	$phpmailer->Username = $setting_website['username'];	$phpmailer->Password = $setting_website['password'];	// Sender and recipient settings	$phpmailer->From = $setting_website['from'];;	$phpmailer->FormName = $setting_website['FormName'];}add_action('phpmailer_init', 'tnw_send_mail_config');